-- Experimental preparation only: no spending authorization, dispatch, cron or provider call.
create table public.analysis_jev_hybrid_plans(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),establishment_id uuid not null references public.establishments(id),
 source_snapshot_id uuid not null references public.analysis_jev_pilot_snapshots(id),version text not null check(version='jev-hybrid-evidence-report-v1'),language text not null check(language in('fr','vi')),
 source_sha256 text not null,dossier_sha256 text not null,prompt_sha256 text not null,schema_sha256 text not null,statistics_sha256 text not null,result_sha256 text not null check(result_sha256~'^[a-f0-9]{64}$'),
 body jsonb not null,paid_enabled boolean not null default false check(not paid_enabled),production_enabled boolean not null default false check(not production_enabled),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(source_snapshot_id,language,result_sha256)
);
create table public.analysis_jev_hybrid_authorizations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),plan_id uuid not null references public.analysis_jev_hybrid_plans(id),
 status text not null default 'blocked' check(status='blocked'),manual_cost_confirmation boolean not null default false check(not manual_cost_confirmation),max_calls int not null default 1 check(max_calls=1),
 max_cost_usd numeric not null check(max_cost_usd>=0),plan_sha256 text not null,dossier_sha256 text not null,prompt_sha256 text not null,schema_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now()
);
create table public.analysis_jev_hybrid_jobs(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),plan_id uuid not null references public.analysis_jev_hybrid_plans(id),authorization_id uuid not null unique references public.analysis_jev_hybrid_authorizations(id),
 language text not null check(language in('fr','vi')),status text not null default 'blocked' check(status in('blocked','queued','running','completed','invalid_output','billing_uncertain','cancelled')),
 request_count int not null default 0 check(request_count between 0 and 1),automatic_retry boolean not null default false check(not automatic_retry),
 lease_owner text,lease_until timestamptz,requested_model text not null default 'gpt-6.1-sol' check(requested_model='gpt-6.1-sol'),served_model text,response_id text,
 input_tokens bigint,output_tokens bigint,cost_usd numeric,duration_ms bigint,raw_response jsonb,validated_result jsonb,error_code text,
 dossier_sha256 text not null,prompt_sha256 text not null,schema_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz
);
create unique index hybrid_one_active_job on public.analysis_jev_hybrid_jobs(plan_id,language) where status in('queued','running','billing_uncertain');
create table public.analysis_jev_hybrid_verdicts(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),job_id uuid not null references public.analysis_jev_hybrid_jobs(id),evidence_id text not null,theme_key text not null,polarity text not null check(polarity in('positive','negative')),
 status text not null check(status in('supported','unsupported','uncertain')),justification text not null,quote text not null,quote_sha256 text not null,source text not null default 'sol_same_verification_writing_call' check(source='sol_same_verification_writing_call'),human_validated boolean not null default false check(not human_validated),created_at timestamptz not null default now(),unique(job_id,evidence_id)
);
create table public.analysis_jev_hybrid_events(
 id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id),plan_id uuid references public.analysis_jev_hybrid_plans(id),job_id uuid references public.analysis_jev_hybrid_jobs(id),actor_user_id uuid not null references auth.users(id),action text not null,payload jsonb not null default '{}',created_at timestamptz not null default now()
);
create table public.analysis_jev_hybrid_controls(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),version text not null check(version='jev-hybrid-independent-control-v1'),body jsonb not null,result_sha256 text not null check(result_sha256~'^[a-f0-9]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,version)
);
do $$declare t text;begin foreach t in array array['analysis_jev_hybrid_plans','analysis_jev_hybrid_authorizations','analysis_jev_hybrid_jobs','analysis_jev_hybrid_verdicts','analysis_jev_hybrid_events','analysis_jev_hybrid_controls'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);
 execute format('create policy hybrid_org_read on public.%I for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=%I.organization_id and m.user_id=(select auth.uid()) and m.role in(''owner'',''admin'',''manager'')))',t,t);
 execute format('create index %I on public.%I(organization_id)',t||'_org',t);
 if t<>'analysis_jev_hybrid_jobs' then execute format('create trigger hybrid_immutable before update or delete on public.%I for each row execute function public.pilot_evidence_immutable()',t);end if;
end loop;end $$;
create index hybrid_plan_est on public.analysis_jev_hybrid_plans(establishment_id);create index hybrid_plan_snapshot on public.analysis_jev_hybrid_plans(source_snapshot_id);create index hybrid_plan_actor on public.analysis_jev_hybrid_plans(created_by);
create index hybrid_auth_plan on public.analysis_jev_hybrid_authorizations(plan_id);create index hybrid_auth_actor on public.analysis_jev_hybrid_authorizations(created_by);
create index hybrid_job_plan on public.analysis_jev_hybrid_jobs(plan_id);create index hybrid_job_actor on public.analysis_jev_hybrid_jobs(created_by);
create index hybrid_verdict_job on public.analysis_jev_hybrid_verdicts(job_id);create index hybrid_event_plan on public.analysis_jev_hybrid_events(plan_id);create index hybrid_event_job on public.analysis_jev_hybrid_events(job_id);create index hybrid_event_actor on public.analysis_jev_hybrid_events(actor_user_id);create index hybrid_control_actor on public.analysis_jev_hybrid_controls(created_by);
create function public.save_hybrid_preparation(p_user uuid,p_source uuid,p_body jsonb,p_sha text,p_control jsonb,p_control_sha text) returns uuid language plpgsql security invoker set search_path='' as $$
declare s public.analysis_jev_pilot_snapshots;pid uuid;begin
 select * into s from public.analysis_jev_pilot_snapshots where id=p_source;
 if s.id is null or not exists(select 1 from public.organization_members where organization_id=s.organization_id and user_id=p_user and role in('owner','admin','manager')) then raise exception 'FORBIDDEN';end if;
 if p_body->>'version' is distinct from 'jev-hybrid-evidence-report-v1' or p_body->>'source_sha256' is distinct from s.source_sha256 or p_body->>'source_snapshot_id' is distinct from s.id::text or p_body->>'organization_id' is distinct from s.organization_id::text or p_body->>'establishment_id' is distinct from s.establishment_id::text or p_body->>'jev_configuration' is distinct from 'v12_economy_1pass_v1' or p_body->>'paid_enabled' is distinct from 'false' or p_body->>'production_enabled' is distinct from 'false' or p_body->>'simulation' is distinct from 'true' or p_body->'sol_response' is distinct from 'null'::jsonb or p_body->>'new_paid_calls' is distinct from '0' then raise exception 'HYBRID_SCOPE_INVALID';end if;
 if p_sha is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body),'sha256'),'hex') or p_body->>'dossier_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body->'packet'),'sha256'),'hex') or p_body->>'prompt_sha256' is distinct from encode(extensions.digest(p_body->>'prompt','sha256'),'hex') or p_body->>'schema_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body->'schema'),'sha256'),'hex') or p_body->>'statistics_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body->'analytics'),'sha256'),'hex') then raise exception 'HYBRID_HASH_CHANGED';end if;
 if p_body->'selected' is distinct from p_body->'packet'->'evidence' or p_body->'analytics' is distinct from p_body->'packet'->'statistics' or jsonb_array_length(p_body->'selected')>32 or exists(select 1 from jsonb_array_elements(p_body->'selected') e where e->>'status'='explicitly_contested' or not exists(select 1 from jsonb_array_elements(s.source->'reviews') r where r->>'id'=e->>'review_id' and r->>'analysis_text_sha256'=e->>'analysis_text_sha256' and strpos(r->>'analysis_text',e->>'quote')>0 and strpos(r->>'analysis_text',e->>'context')>0 and encode(extensions.digest(e->>'quote','sha256'),'hex')=e->>'quote_sha256')) then raise exception 'HYBRID_QUOTE_CHANGED';end if;
 if jsonb_array_length(p_body->'analytics'->'themes')<>25 or (p_body->'analytics'->'coverage'->>'stored_reviews')::int<>jsonb_array_length(s.source->'reviews') or (p_body->'analytics'->'coverage'->>'google_total')::int<>(s.source->>'google_total_reviews')::int then raise exception 'HYBRID_STATS_CHANGED';end if;
 if exists(select 1 from jsonb_array_elements(p_body->'cache_fingerprints') f where not exists(select 1 from public.analysis_jev_review_cache c where c.id=(f->>'cache_id')::uuid and c.organization_id=s.organization_id and c.establishment_id=s.establishment_id and c.status='completed' and c.configuration_id='v12_economy_1pass_v1' and c.review_id=(f->>'review_id')::uuid and c.analysis_text_sha256=f->>'text_sha256' and encode(extensions.digest(public.jev_economy_canonical(jsonb_build_object('cache_key',c.cache_key,'response',c.response,'theme_results',c.theme_results,'served_model',c.served_model)),'sha256'),'hex')=f->>'response_sha256')) then raise exception 'HYBRID_CACHE_CHANGED';end if;
 if (p_body->'analytics'->'coverage'->>'analysed_reviews')::int<>jsonb_array_length(p_body->'cache_fingerprints') or (select count(distinct f->>'review_id') from jsonb_array_elements(p_body->'cache_fingerprints') f)<>jsonb_array_length(p_body->'cache_fingerprints') then raise exception 'HYBRID_CACHE_SCOPE_INVALID';end if;
 -- Independent SQL counts for each of the 25 persisted theme choices; mentions and distinct reviews remain separate.
 if exists(select 1 from jsonb_array_elements(p_body->'analytics'->'themes') t where (t->>'positive_mentions')::int<>(select count(*) from jsonb_array_elements(p_body->'cache_fingerprints') f join public.analysis_jev_review_cache c on c.id=(f->>'cache_id')::uuid where c.theme_results->(t->>'theme_key')->>'choice' in('positive','both')) or (t->>'negative_mentions')::int<>(select count(*) from jsonb_array_elements(p_body->'cache_fingerprints') f join public.analysis_jev_review_cache c on c.id=(f->>'cache_id')::uuid where c.theme_results->(t->>'theme_key')->>'choice' in('negative','both')) or (t->>'distinct_reviews')::int<>(select count(distinct c.review_id) from jsonb_array_elements(p_body->'cache_fingerprints') f join public.analysis_jev_review_cache c on c.id=(f->>'cache_id')::uuid where c.theme_results->(t->>'theme_key')->>'choice'<>'absent')) then raise exception 'HYBRID_SQL_THEME_COUNTS_CHANGED';end if;
 if p_control->>'version' is distinct from 'jev-hybrid-independent-control-v1' or p_control->>'organization_id' is distinct from s.organization_id::text or p_control->>'reference_labels' is distinct from '0' or p_control->>'paid_calls' is distinct from '0' or p_control_sha is distinct from encode(extensions.digest(public.jev_economy_canonical(p_control),'sha256'),'hex') or exists(select 1 from jsonb_array_elements(p_control->'items') i where i->>'establishment_id'=s.establishment_id::text or i->'reference_choice' is distinct from 'null'::jsonb or i->'jev_result' is distinct from 'null'::jsonb or not exists(select 1 from public.reviews r where r.id=(i->>'review_id')::uuid and r.organization_id=s.organization_id and r.establishment_id=(i->>'establishment_id')::uuid)) then raise exception 'HYBRID_CONTROL_INVALID';end if;
 perform pg_advisory_xact_lock(hashtextextended(s.id::text||':'||(p_body->>'language')||':'||p_sha,0));
 select id into pid from public.analysis_jev_hybrid_plans where source_snapshot_id=s.id and language=p_body->>'language' and result_sha256=p_sha;if found then return pid;end if;
 insert into public.analysis_jev_hybrid_plans(organization_id,establishment_id,source_snapshot_id,version,language,source_sha256,dossier_sha256,prompt_sha256,schema_sha256,statistics_sha256,result_sha256,body,created_by) values(s.organization_id,s.establishment_id,s.id,p_body->>'version',p_body->>'language',s.source_sha256,p_body->>'dossier_sha256',p_body->>'prompt_sha256',p_body->>'schema_sha256',p_body->>'statistics_sha256',p_sha,p_body,p_user) returning id into pid;
 insert into public.analysis_jev_hybrid_controls(organization_id,version,body,result_sha256,created_by) values(s.organization_id,p_control->>'version',p_control,p_control_sha,p_user) on conflict(organization_id,version) do nothing;
 if not exists(select 1 from public.analysis_jev_hybrid_controls where organization_id=s.organization_id and version=p_control->>'version' and result_sha256=p_control_sha) then raise exception 'HYBRID_CONTROL_CHANGED';end if;
 insert into public.analysis_jev_hybrid_events(organization_id,plan_id,actor_user_id,action,payload) values(s.organization_id,pid,p_user,'free_preparation_frozen',jsonb_build_object('paid_calls',0));return pid;
end $$;
create function public.start_hybrid_report(p_plan uuid,p_confirm boolean) returns uuid language plpgsql security invoker set search_path='' as $$begin raise exception 'HYBRID_PAID_EXECUTION_DISABLED';end $$;
create function public.claim_hybrid_job(p_job uuid,p_worker text) returns boolean language plpgsql security invoker set search_path='' as $$begin raise exception 'HYBRID_PAID_EXECUTION_DISABLED';end $$;
create function public.hybrid_job_attempt_guard() returns trigger language plpgsql set search_path='' as $$begin
 if old.status in('completed','invalid_output','cancelled') then raise exception 'HYBRID_JOB_IMMUTABLE';end if;
 if old.request_count=1 and new.status in('queued','running') and (old.status<>'running' or old.lease_owner is distinct from new.lease_owner or old.lease_until<now()) then raise exception 'HYBRID_NO_PAID_RETRY';end if;
 if new.request_count<old.request_count then raise exception 'HYBRID_ATTEMPT_COUNTER_IMMUTABLE';end if;return new;end $$;
create trigger hybrid_job_guard before update on public.analysis_jev_hybrid_jobs for each row execute function public.hybrid_job_attempt_guard();
revoke all on function public.save_hybrid_preparation(uuid,uuid,jsonb,text,jsonb,text),public.start_hybrid_report(uuid,boolean),public.claim_hybrid_job(uuid,text),public.hybrid_job_attempt_guard() from public,anon,authenticated;
grant execute on function public.save_hybrid_preparation(uuid,uuid,jsonb,text,jsonb,text),public.start_hybrid_report(uuid,boolean),public.claim_hybrid_job(uuid,text) to service_role;
